import java.util.*;

public class Solution {
  static class Node {
    int value;
    Node left, right;

    Node(int v) {
      value = v;
    }
  }

  static Node sample() {
    Node r = new Node(4);
    r.left = new Node(2);
    r.right = new Node(6);
    r.left.left = new Node(1);
    r.left.right = new Node(3);
    r.right.left = new Node(5);
    r.right.right = new Node(7);
    return r;
  }

  static void inorder(Node r, List<Integer> out) {
    if (r != null) {
      inorder(r.left, out);
      out.add(r.value);
      inorder(r.right, out);
    }
  }

  static String view(Node r) {
    List<Integer> a = new ArrayList<>();
    inorder(r, a);
    return a.toString();
  }

  private static void scan(Node r, Node[] state) {
    if (r == null) return;
    scan(r.left, state);
    if (state[0] != null && state[0].value > r.value) {
      if (state[1] == null) state[1] = state[0];
      state[2] = r;
    }
    state[0] = r;
    scan(r.right, state);
  }

  public static void solve(Node r) {
    Node[] s = new Node[3];
    scan(r, s);
    if (s[1] != null) {
      int t = s[1].value;
      s[1].value = s[2].value;
      s[2].value = t;
    }
  }

  public static void main(String[] args) {
    Node r = sample();
    int t = r.left.value;
    r.left.value = r.right.value;
    r.right.value = t;
    solve(r);
    System.out.println(view(r));
  }
}

